THEME = ("T03", "Contrôle d'accès obligatoire et confidentialité (MAC, Bell-LaPadula)")
SOURCE = "Bell et LaPadula, « Secure Computer Systems: Mathematical Foundations », MITRE, 1973 ; TCSEC (1985) ; Denning, « A Lattice Model of Secure Information Flow », 1976 ⚠ à vérifier"
Q = [
(1,"Dans un contrôle d'accès obligatoire (MAC), qui impose la politique ?","Le système, selon des règles centrales","Chaque propriétaire de fichier","L'utilisateur qui lit le fichier","Le fabricant du disque",
 "En MAC, l'utilisateur ne peut pas modifier les règles, même pour ses propres fichiers."),
(1,"Que contient une étiquette de sécurité ?","Un niveau de classification, parfois complété de catégories","Le mot de passe du propriétaire","La taille du fichier","L'adresse IP du serveur",
 "Les sujets ont une habilitation, les objets une classification : on les compare."),
(1,"Que désigne l'habilitation d'un sujet ?","Le niveau maximal d'information auquel il a le droit d'accéder","Son niveau de salaire","Son nombre de connexions","Son type d'ordinateur",
 "L'habilitation est accordée à la personne après vérification, par exemple Confidentiel."),
(1,"Quel est l'ordre croissant des niveaux dans l'exemple Public, Interne, Confidentiel, Secret ?","Public < Interne < Confidentiel < Secret","Secret < Confidentiel < Interne < Public","Interne < Public < Secret < Confidentiel","Confidentiel < Secret < Public < Interne",
 "Plus le niveau monte, plus l'information est sensible."),
(1,"Que garantit le modèle de Bell-LaPadula ?","La confidentialité","L'intégrité des transactions","La disponibilité","La non-répudiation",
 "Il a été conçu en 1973 pour empêcher les fuites d'information vers les personnes non habilitées."),
(1,"Quelle règle énonce la propriété de sécurité simple de Bell-LaPadula ?","Pas de lecture vers le haut (no read up)","Pas d'écriture vers le haut","Pas de lecture vers le bas","Pas d'exécution vers le bas",
 "Un sujet ne lit pas un objet de niveau supérieur à son habilitation."),
(1,"Quelle règle énonce la propriété étoile (*) de Bell-LaPadula ?","Pas d'écriture vers le bas (no write down)","Pas de lecture vers le haut","Pas d'écriture vers le haut","Pas de lecture vers le bas",
 "Un sujet n'écrit pas dans un objet de niveau inférieur, pour ne pas faire fuiter l'information."),
(2,"Un sujet Confidentiel veut lire un document Interne. Que dit BLP ?","Permis : lecture vers le bas","Refusé : lecture vers le haut","Refusé : écriture vers le bas","Permis uniquement si le document est modifié",
 "Un niveau supérieur peut lire les niveaux inférieurs ou égaux."),
(2,"Un sujet Interne veut lire un document Confidentiel. Que dit BLP ?","Refusé : lecture vers le haut","Permis : lecture vers le bas","Permis si le sujet est propriétaire","Permis en écriture seulement",
 "Règle « no read up » : son habilitation est inférieure à la classification."),
(2,"Un sujet Confidentiel veut écrire dans un document Interne. Que dit BLP ?","Refusé : écriture vers le bas","Permis : écriture vers le bas","Permis si le document est ancien","Permis après approbation du propriétaire",
 "Il pourrait y recopier de l'information confidentielle : c'est ce que la propriété étoile interdit."),
(2,"Un sujet Interne veut écrire dans un document Confidentiel. Que dit BLP ?","Permis par la propriété étoile (écriture vers le haut)","Refusé : lecture vers le haut","Refusé : écriture vers le bas","Refusé car il est propriétaire",
 "BLP n'interdit pas l'écriture vers le haut pour la confidentialité, même si l'intégrité pose question."),
(2,"Quelle est la conséquence pratique de la propriété étoile pour un sujet de niveau Secret ?","Il ne peut pas enregistrer ses résultats dans un fichier Public","Il ne peut pas lire de fichiers Secret","Il peut écrire partout","Il ne peut qu'exécuter",
 "Pour éviter les fuites, ses sorties sont au minimum au niveau Secret."),
(2,"Pourquoi BLP interdit-il l'écriture vers le bas ?","Pour empêcher qu'un programme ou une personne recopie une information sensible dans un objet moins protégé","Pour économiser de l'espace disque","Pour accélérer le système","Pour limiter la taille des fichiers",
 "Même sans intention, un programme infecté pourrait faire fuiter des données vers un niveau plus bas."),
(2,"Quel terme désigne le niveau le plus bas d'un treillis de sécurité ?","Le niveau public (ou non classifié)","Le niveau secret","Le niveau administrateur","Le niveau racine",
 "Le treillis (lattice) ordonne les niveaux et les catégories."),
(2,"Que sont les catégories (ou compartiments) ajoutées aux niveaux ?","Des domaines d'activité qui compartimentent l'information","Des types de fichiers","Des tailles de fichiers","Des versions de logiciels",
 "Elles mettent en œuvre le besoin d'en connaître : être Confidentiel ne suffit pas si on n'est pas dans le bon compartiment."),
(3,"Sujet (Confidentiel, {Logistique}) et objet (Interne, {Logistique, Finance}). Peut-il lire ?","Non : il ne possède pas la catégorie Finance","Oui : son niveau est supérieur","Oui : Logistique suffit","Non : le niveau est trop bas",
 "Domination : niveau ≥ et catégories de l'objet incluses dans celles du sujet. Ici Finance manque."),
(3,"Sujet (Secret, {A, B}) et objet (Confidentiel, {A}). Peut-il lire ?","Oui : niveau supérieur et catégorie incluse","Non : la catégorie B est en trop","Non : le niveau est trop haut","Oui, mais seulement en écriture",
 "Le sujet domine l'objet : niveau plus élevé et ensemble de catégories qui contient celui de l'objet."),
(3,"Sujet (Interne, {A}) et objet (Confidentiel, {A}). Peut-il lire ?","Non : niveau insuffisant","Oui : la catégorie correspond","Oui : lecture vers le bas","Non : le sujet n'a pas de catégorie",
 "La catégorie est bonne mais le niveau est inférieur : la domination échoue."),
(3,"Que veut dire « un sujet domine un objet » ?","Son niveau est supérieur ou égal et ses catégories incluent celles de l'objet","Son niveau est strictement supérieur","Il possède l'objet","Il l'a créé avant les autres",
 "C'est la relation d'ordre partiel du treillis de sécurité."),
(2,"Qu'est-ce que la propriété de sécurité discrétionnaire de BLP ?","Un accès doit aussi être permis par la matrice d'accès","Elle remplace le MAC","Elle interdit tout accès","Elle supprime les catégories",
 "BLP combine règles obligatoires et contrôle discrétionnaire : les deux doivent autoriser."),
(3,"Que signifie la tranquillité (tranquility) dans BLP ?","Les niveaux des sujets et objets ne changent pas pendant l'utilisation","Le système ne produit pas de bruit","Les accès sont lents","Aucun accès n'est refusé",
 "La forte tranquillité fige les étiquettes ; la faible permet leur évolution sans violer la politique."),
(2,"Qu'est-ce qu'un canal caché (covert channel) ?","Un moyen détourné de faire passer de l'information malgré la politique","Un canal chiffré de messagerie","Un VPN","Un câble réseau caché",
 "Par exemple en modulant l'utilisation d'une ressource partagée ; BLP ne les prévient pas."),
(3,"Pourquoi BLP ne protège-t-il pas contre l'intégrité des données ?","Il ne contrôle que la fuite d'information, pas sa modification par un niveau inférieur","Il interdit la lecture","Il ne gère pas les étiquettes","Il exige un administrateur",
 "Un sujet de bas niveau peut écrire vers le haut : le modèle de Biba traite l'intégrité."),
(2,"Quel système Linux met en œuvre un contrôle d'accès obligatoire ?","SELinux","chmod","sudo","cron",
 "SELinux (développé avec la NSA) applique une politique indépendante des choix des utilisateurs."),
(2,"Que fait SELinux en plus des permissions Unix ?","Il applique une politique centrale par contextes de sécurité","Il remplace les mots de passe","Il chiffre les disques","Il supprime les groupes",
 "Une action doit être autorisée par les permissions classiques et par la politique SELinux."),
(2,"Qu'est-ce qu'un « domaine » dans SELinux ?","Le contexte de sécurité d'un processus qui détermine ce qu'il peut faire","Un nom de site web","Un annuaire","Un groupe d'utilisateurs",
 "Par exemple un serveur web est confiné dans son domaine et ne peut pas lire les fichiers d'un autre."),
(2,"Quel avantage a SELinux face à un serveur web compromis ?","Il limite les fichiers que le processus compromis peut atteindre","Il empêche toute faille","Il supprime le serveur","Il chiffre les pages",
 "Même root dans le service reste confiné par la politique : l'impact est réduit."),
(2,"Quel mode SELinux journalise sans bloquer ?","Permissive","Enforcing","Disabled","Strict",
 "Le mode permissive aide à écrire la politique ; enforcing applique les refus."),
(2,"Que fait-on généralement face à un blocage SELinux inattendu ?","On analyse les journaux et on adapte la politique ou l'étiquette","On désactive définitivement SELinux","On donne les droits 777","On redémarre le serveur chaque heure",
 "Désactiver SELinux supprime une couche de défense : on corrige la cause."),
(2,"Quelle fonction a AppArmor ?","Confiner des programmes par profil de chemins autorisés","Gérer les mots de passe","Faire des sauvegardes","Router le trafic",
 "AppArmor est un MAC par profil, plus simple que SELinux mais fondé sur les chemins."),
(1,"Quel est le principal avantage du MAC ?","Une politique uniforme que les utilisateurs ne peuvent pas contourner","La souplesse du partage","L'absence d'administration","La rapidité d'écriture",
 "Il offre une garantie forte pour les données sensibles."),
(1,"Quel est le principal inconvénient du MAC ?","Une administration lourde et peu souple","Il est invisible","Il n'a pas de politique","Il supprime les journaux",
 "Classifier, habiliter et maintenir la politique demande beaucoup de rigueur."),
(2,"Dans quel contexte le MAC est-il le plus courant ?","Défense, renseignement, systèmes très sensibles","Réseaux sociaux","Jeux vidéo","Blogs personnels",
 "C'est là que la classification officielle impose un contrôle imposé."),
(2,"Pourquoi une PME de transport sans donnée classifiée utiliserait-elle rarement un MAC multi-niveaux ?","Le coût de classification dépasse le bénéfice","Il est interdit","Il ne fonctionne pas en PME","Il exige un datacenter",
 "Les rôles ou attributs suffisent souvent pour ses besoins, avec moins de charge d'administration."),
(3,"Que se passe-t-il si un sujet Secret est autorisé à écrire en Public dans BLP ?","Une fuite devient possible par recopie","Rien : l'écriture est sûre","Le niveau Public devient Secret automatiquement","Le fichier est chiffré",
 "C'est exactement la violation de la propriété étoile."),
(3,"Comment résoudre en pratique le besoin d'un officier Secret de produire un rapport Public ?","Par une procédure de déclassification contrôlée par un relecteur habilité","En l'autorisant à écrire en Public","En supprimant la propriété étoile","En copiant à la main sans contrôle",
 "La déclassification explicite passe par des sujets de confiance et une revue."),
(3,"Qu'est-ce qu'un « sujet de confiance » (trusted subject) dans BLP ?","Un sujet exempté de la propriété étoile pour des fonctions précises","Un utilisateur sans mot de passe","Un administrateur de base de données","Un compte invité",
 "Il doit être vérifié rigoureusement, car son exemption ouvre un risque de fuite."),
(2,"Quel sigle désigne l'évaluation des systèmes de confiance américains de 1985 ?","TCSEC (Orange Book)","ISO 27001","RGPD","PCI DSS",
 "Le livre orange classe les systèmes par niveaux de confiance, avec le MAC dès la classe B."),
(2,"Quel est l'effet d'une étiquette de sécurité sur un objet nouvellement créé par un sujet ?","L'objet reçoit au moins le niveau du sujet","L'objet reste sans étiquette","L'objet est supprimé","L'objet devient Public",
 "Pour respecter *-propriété, la création hérite du niveau du créateur."),
(2,"Quelle étiquette recevrait un document de synthèse compilant un fichier Interne et un fichier Confidentiel ?","Au moins Confidentiel","Public","Interne","Aucune",
 "Le résultat doit dominer toutes ses sources : on prend le niveau le plus haut."),
(3,"Quel phénomène décrit l'agrégation d'informations peu sensibles qui, réunies, deviennent sensibles ?","Le problème d'agrégation","La déclassification","La tranquillité","La délégation",
 "Un ensemble peut avoir un niveau supérieur à celui de ses éléments pris isolément."),
(3,"Qu'est-ce que le problème d'inférence ?","Déduire une information sensible à partir de données autorisées","Chiffrer plus vite","Supprimer un journal","Dupliquer une base",
 "Un attaquant recoupe des résultats permis pour reconstituer une donnée interdite."),
(2,"Quelle modalité de BLP s'applique au droit d'exécution ?","Selon l'implémentation, souvent comme une lecture","Elle n'existe pas","Toujours interdite","Toujours permise",
 "Exécuter un programme revient à en lire le contenu pour la politique de confidentialité."),
(1,"Quel est le rôle d'un administrateur de sécurité en MAC ?","Définir et maintenir les étiquettes et la politique","Décider des droits pour chaque fichier utilisateur","Supprimer les journaux","Gérer le réseau électrique",
 "La politique est centralisée : ce sont les administrateurs de sécurité qui la gèrent."),
(2,"Comment appelle-t-on un modèle MAC qui ordonne niveaux et catégories ?","Un treillis (lattice)","Un arbre binaire","Un annuaire","Une table de hachage",
 "Dénommé modèle de Denning : chaque paire de niveaux a un plus petit majorant et un plus grand minorant."),
(2,"Dans un treillis, quel niveau combine (Interne, {A}) et (Confidentiel, {B}) pour le plus petit majorant ?","(Confidentiel, {A, B})","(Interne, {A})","(Interne, {B})","(Public, {})",
 "Le plus petit majorant prend le niveau le plus élevé et l'union des catégories."),
(3,"Quel est le plus grand minorant de (Confidentiel, {A, B}) et (Secret, {B, C}) ?","(Confidentiel, {B})","(Secret, {A, B, C})","(Confidentiel, {A, B, C})","(Secret, {B})",
 "Le plus grand minorant prend le niveau le plus bas et l'intersection des catégories."),
(2,"Quelle règle empêche un utilisateur Interne de modifier un rapport Secret en confidentialité pure BLP ?","Aucune : BLP autorise l'écriture vers le haut","La propriété simple","La propriété étoile","La tranquillité",
 "Cela montre pourquoi on associe Biba ou Clark-Wilson pour l'intégrité."),
]
